// concept-definitions-001-closure: On a concept host the step-definitions check fails a definition recording no declared concept of its step's block and a step binding two definitions, and passes a Scenario whose every step binds one definition recording its concept
func TestConceptDefinitions001Closure(t *testing.T) {
	s := scenarios.New(t, "concept-definitions-001-closure")
	s.Given(`the "concept-definitions-closure" project tree`)
	s.When(`the Quality Engineer runs "scen check"`)
	s.Then(`the command exits with code 1`)
	s.And(`stdout matches check=step-definitions subjectID=calc-001-halve promptIndex=1 answer=fail context=.*the Owner halves 6.*which records no concept`)
	s.And(`stdout matches check=step-definitions subjectID=calc-002-double promptIndex=1 answer=fail context=.*the Owner doubles 6.* binds to 2 step definitions`)
	s.And(`stdout matches check=step-definitions subjectID=calc-004-even promptIndex=1 answer=fail context=.*the result is even.*halving.*, which is not a declared then concept`)
	s.And(`stdout matches check=step-definitions subjectID=calc-003-double promptIndex=1 answer=pass`)
	s.And(`the engine dispatched no AI turns`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}
